import Foundation

/// 防火管理人訓練專業機構通訊錄（155 筆，原始 CSV 為 Big5/CP950）
struct FieldFireTrainingInstitution: Identifiable, Hashable {
    let id: String
    let sequence: Int
    let region: FieldHospital.Region
    let city: String
    let name: String
    let postcode: String
    let address: String
    let phone: String
    let fax: String
    let email: String
    let website: String
    let contact: String

    var emailURL: URL? {
        guard !email.isEmpty else { return nil }
        var components = URLComponents()
        components.scheme = "mailto"
        components.path = email
        return components.url
    }

    var websiteURL: URL? {
        guard !website.isEmpty else { return nil }
        let normalizedWebsite = website.hasPrefix("http://") || website.hasPrefix("https://") ? website : "https://\(website)"
        return URL(string: normalizedWebsite)
    }

    var mapsURL: URL? {
        let query = [name, address].filter { !$0.isEmpty }.joined(separator: " ")
        guard !query.isEmpty else { return nil }
        var components = URLComponents(string: "http://maps.apple.com/")
        components?.queryItems = [URLQueryItem(name: "q", value: query)]
        return components?.url
    }
}

